<!-- NestedList.svelte
A Svelte component for rendering a nested list structure. This component takes an array of items, 
each potentially containing its own nested items, and renders them as a hierarchical list with 
customizable classes for `<li>` and `<a>` elements.

Usage Example:
<NestedList items={[
  { label: 'Item 1', href: '#', liClass: 'item-class', aClass: 'link-class', children: [
    { label: 'Subitem 1.1', href: '#', liClass: 'subitem-class', aClass: 'sublink-class', children: [] }
  ]},
  { label: 'Item 2', href: '#', liClass: 'item-class', aClass: 'link-class', children: [] }
]} />

Props:
- items (Object[]): The array of items to render in the list. Each item is an object that can contain:
  - label (string): The text content for the list item.
  - liClass (string): Optional CSS class for the `<li>` element.
  - aClass (string): Optional CSS class for the `<a>` element.
  - children (Object[]): Optional array of nested items to be rendered as a sublist.
- class (string): Optional CSS class for the outer `<ul>`.
- liClass (string): Default class for every `<li>`, overridden per item.
- aClass (string): Default class for every `<a>`, overridden per item.
-->
<script>
  const {
    items = [],
    class: klass = '',
    liClass = '',
    aClass = '',
    ...rest
  } = $props()

  function parseItemProps(item) {
    const {
      label,
      children,
      liClass: ilClass,
      aClass: iaClass,
      href,
      'aria-current': ariaCurrent,
      ...irest
    } = item

    return {
      liProps: {
        class: ilClass || liClass,
        ...irest,
      },
      aProps: {
        class: iaClass || aClass,
        href,
        'aria-current': ariaCurrent,
      },
    }
  }
</script>

{#snippet nestedItems(items)}
  {#if items.length}
    {#each items as item (item.label)}
      {@const { liProps, aProps } = parseItemProps(item)}
      <li {...liProps}>
        <a {...aProps}>
          {item.label}
        </a>

        {#if item.children.length}
          <ul>
            {@render nestedItems(item.children)}
          </ul>
        {/if}
      </li>
    {/each}
  {/if}
{/snippet}

<ul {...rest} class={klass}>
  {@render nestedItems(items)}
</ul>
